function validate(input) {
  const [obj1, obj2] = input;
  for (const value of [obj1, obj2]) {
    if (value === null || typeof value !== 'object') return 'obj1 and obj2 must be JSON objects or arrays.';
    if (JSON.stringify(value).length > 10000) return 'Keep each value under 10,000 characters of JSON.';
    const stack = [[value, 1]];
    while (stack.length) {
      const [item, depth] = stack.pop();
      if (item === null || typeof item !== 'object') continue;
      if (depth > 10) return 'Keep obj1 and obj2 at most 10 levels deep.';
      if (!Array.isArray(item) && Object.hasOwn(item, '__proto__')) return 'Keys named "__proto__" are not allowed.';
      for (const key of Object.keys(item)) stack.push([item[key], depth + 1]);
    }
  }
  if (Array.isArray(obj1) !== Array.isArray(obj2)) return 'obj1 and obj2 must both be objects or both be arrays.';
  return null;
}

