function objDiff(obj1, obj2) {
  // Walk obj2's keys instead; walk returns null for "no difference".
  const kind = value => (value === null ? 'null' : Array.isArray(value) ? 'array' : typeof value);
  const walk = (a, b) => {
    if (kind(a) !== kind(b)) return [a, b];
    if (kind(a) !== 'array' && kind(a) !== 'object') return a === b ? null : [a, b];
    const out = {};
    let found = false;
    for (const key in b) {
      if (!Object.prototype.hasOwnProperty.call(a, key)) continue;
      const inner = walk(a[key], b[key]);
      if (inner !== null) {
        out[key] = inner;
        found = true;
      }
    }
    return found ? out : null;
  };
  return walk(obj1, obj2) || {};
}

