function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['a', 'b', 'c', 'v', 'x', 'z'];
  let budget = small ? 12 : 900;
  const primitive = () => {
    const roll = rand();
    if (roll < 0.45) return Math.floor(rand() * 7) - 2;
    if (roll < 0.7) return pick(['', 'a', 'b', '1']);
    if (roll < 0.85) return rand() < 0.5;
    return null;
  };
  const value = (depth, container) => {
    budget--;
    if (!container && (depth >= (small ? 3 : 7) || budget <= 0 || rand() < 0.45)) return primitive();
    const length = depth === 0 && !small ? 60 : Math.floor(rand() * (small ? 4 : 6));
    if (rand() < 0.5) return Array.from({ length }, () => value(depth + 1, false));
    const object = {};
    for (let i = 0; i < length; i++) object[pick(names) + (small ? '' : i)] = value(depth + 1, false);
    return object;
  };
  // A changed copy: values are kept, replaced or dropped, arrays grow or shrink, and nested kinds may change.
  const mutate = (item, depth) => {
    if (item === null || typeof item !== 'object') {
      const roll = rand();
      if (roll < 0.6) return item;
      if (roll < 0.88) return primitive();
      return rand() < 0.5 ? [] : { a: primitive() };
    }
    if (depth > 0 && rand() < 0.08) return Array.isArray(item) ? Object.assign({}, item) : Object.values(item);
    if (Array.isArray(item)) {
      const out = item.map(child => mutate(child, depth + 1));
      const roll = rand();
      if (roll < 0.25) out.length = Math.floor(rand() * (out.length + 1));
      else if (roll < 0.5) out.push(primitive());
      return out;
    }
    const out = {};
    for (const key of Object.keys(item)) if (rand() < 0.9) out[key] = mutate(item[key], depth + 1);
    if (rand() < 0.3) out[pick(names) + 'new'] = primitive();
    return out;
  };
  const obj1 = value(0, true);
  const obj2 = rand() < 0.15 ? JSON.parse(JSON.stringify(obj1)) : mutate(obj1, 0);
  return rand() < 0.5 ? [obj1, obj2] : [obj2, obj1];
}
